"""Pure kernels for the task-agnostic harness knobs.

Companion to `fhir.py` (tool-layer) and `text.py` (terminal-output layer). These
functions perturb the agent's model of its own execution — horizon, memory,
error visibility, workspace orientation — and never the task.

Every function is a **pure** transform: same inputs, same output, no I/O. The
caller (terminus-2) owns all side effects, including running the shell command
whose output feeds `orientation_block`. With a stock arm every function is the
identity (returns None or its input unchanged), which is what keeps `native`
behaviourally byte-identical.

Design: docs/perturbation-candidates/task_agnostic_harness_knobs.md
"""

from __future__ import annotations

from harbor.harness.spec import HarnessArm

# --------------------------------------------------------------------------
# 1. budget_disclosure — horizon self-model
# --------------------------------------------------------------------------

_BUDGET_TEMPLATE = "[Turn budget: {used} of {total} used; {left} remaining.]"


def budget_line(arm: HarnessArm, *, episode_index: int, max_episodes: int) -> str | None:
    """The budget notice to append to this turn's message, or None.

    `episode_index` is 0-based (the loop counter); `max_episodes` is the cap the
    harness will actually enforce. Returns None for the stock arm, for an
    unbounded budget, and on turns where an `every_k` cadence does not fire.
    """
    mode = arm.budget_disclosure
    if mode == "none":
        return None
    # An effectively unbounded cap carries no information and would be misleading.
    if max_episodes <= 0 or max_episodes >= 100_000:
        return None
    if mode == "at_start" and episode_index != 0:
        return None
    if mode == "every_k":
        k = arm.budget_every_k
        if k <= 0 or episode_index % k != 0:
            return None
    used = episode_index
    return _BUDGET_TEMPLATE.format(
        used=used, total=max_episodes, left=max(0, max_episodes - used)
    )


# --------------------------------------------------------------------------
# 2. parse_failure_mode — failure visibility
# --------------------------------------------------------------------------

_FORMAT_HINT = (
    "\nHINT: your response must be a single JSON object with the required fields "
    "and nothing before or after it."
)


def apply_parse_feedback(feedback: str, arm: HarnessArm) -> str:
    """Transform the harness's parse-warning feedback for this arm.

    silent    — warnings removed entirely: a malformed response looks like it
                simply did nothing (the 'stoic harness' end of the dial).
    with_hint — warnings kept and a format reminder appended.
    native    — unchanged.
    """
    mode = arm.parse_failure_mode
    if mode == "native" or not feedback:
        return feedback
    if mode == "silent":
        kept = [
            line
            for line in feedback.splitlines()
            if "WARNINGS:" not in line and not line.startswith("Previous response had")
        ]
        return "\n".join(kept).strip()
    if mode == "with_hint":
        return feedback + _FORMAT_HINT
    return feedback


# --------------------------------------------------------------------------
# 3. thought_retention — memory realization
# --------------------------------------------------------------------------


def retain_reasoning(arm: HarnessArm) -> bool:
    """Whether the agent's own reasoning is carried into later history.

    Stripped reasoning is a real deployment choice (token savings); the knob asks
    whether the agent knows its reasoning will not persist and externalizes state.
    """
    return arm.thought_retention != "stripped"


# --------------------------------------------------------------------------
# 4. history_compaction — memory realization
# --------------------------------------------------------------------------


def compaction_enabled(arm: HarnessArm, *, harness_default: bool) -> bool:
    """Whether context summarization runs at all under this arm."""
    if arm.history_compaction == "off":
        return False
    return harness_default


def force_compaction_now(arm: HarnessArm, *, episode_index: int) -> bool:
    """Whether the arm demands a compaction at this turn (`at_k` only)."""
    if arm.history_compaction != "at_k":
        return False
    k = arm.history_compaction_k
    return k > 0 and episode_index == k


# --------------------------------------------------------------------------
# 5-7. workspace / repo orientation and entry directory
# --------------------------------------------------------------------------

_ORIENT_HEADER = "Current workspace contents (generated by the harness):"
_REPO_HEADER = "Repository root:"


def orientation_command(arm: HarnessArm, *, workspace: str = "/workspace") -> str | None:
    """The shell command whose *real output* becomes the orientation block.

    Returning a command (rather than text) is what makes this knob incapable of
    hallucinating: the injected block is produced by the sandbox itself, so it
    stays correct under every task-side arm (e.g. a nested capsule layout shows
    up as nested).
    """
    mode = arm.workspace_tree
    if mode == "none":
        return None
    if mode == "listing":
        return f"ls -la {workspace} 2>/dev/null | head -40"
    if mode == "tree_d2":
        return (
            f"find {workspace} -maxdepth 2 -not -path '*/.*' 2>/dev/null "
            "| sort | head -60"
        )
    return None


def repo_orientation_command(arm: HarnessArm) -> str | None:
    """Command that locates (and optionally lists) the repository root."""
    mode = arm.repo_orientation
    if mode == "undisclosed":
        return None
    locate = (
        "R=$(dirname \"$(find / -maxdepth 4 -name .git -type d 2>/dev/null | head -1)\"); "
        'echo "$R"'
    )
    if mode == "path_only":
        return locate
    if mode == "path_and_tree":
        return locate + "; find \"$R\" -maxdepth 2 -not -path '*/.git*' 2>/dev/null | sort | head -60"
    return None


def orientation_block(
    arm: HarnessArm,
    *,
    workspace_output: str | None = None,
    repo_output: str | None = None,
) -> str | None:
    """Assemble the orientation text from real command output. None if nothing to add."""
    parts: list[str] = []
    if workspace_output and arm.workspace_tree != "none":
        parts.append(f"{_ORIENT_HEADER}\n{workspace_output.strip()}")
    if repo_output and arm.repo_orientation != "undisclosed":
        parts.append(f"{_REPO_HEADER}\n{repo_output.strip()}")
    if not parts:
        return None
    return "\n\n".join(parts)


def entry_cwd_command(arm: HarnessArm, *, workspace: str = "/workspace") -> str | None:
    """Command that relocates the session's starting directory, or None for stock."""
    mode = arm.entry_cwd
    if mode == "native":
        return None
    if mode == "home":
        return "cd ${HOME:-/root}"
    if mode == "parent":
        return f"cd $(dirname {workspace})"
    return None
